// app/core.js — 全局常量、状态变量声明
document.addEventListener("touchstart",function(){},{passive:true});
var $=function(id){return document.getElementById(id)};
/* ---- 全局 UI 动画速度：唯一的倍率来源 ----
   UISPD：1 = 原速，>1 更快，<1 更慢。
   · CSS：所有 UI 时长统一写成 calc(Xs/var(--ui-spd,1))
   · JS：.animate() 的 duration/delay、内联 transition、与动画对齐的 setTimeout 一律用 uiT(毫秒数) 换算；
         弹簧物理循环直接乘 UISPD
   文字舞台特效（逐字/星空/海报等）不受影响，仍由「播放速度 → 动效」的 --aspd 单独控制。 */
var UISPD=1;
function uiT(ms){return ms/UISPD}
function setUiSpd(v){v=+v;if(!(v>0))v=1;UISPD=v;document.documentElement.style.setProperty("--ui-spd",String(v));return v}
window.setUiSpd=setUiSpd;
/* 「系统设置 → 界面动画速度」滑块：范围 0.25×–3×，记住用户的选择（localStorage: uiSpd） */
var UISPD_MIN=.25,UISPD_MAX=3;
function syncUiSpdUI(){
  var e=document.getElementById("uiSpd"),v=document.getElementById("uiSpdV");
  if(e){var pct=Math.round(UISPD*100);if(+e.value!==pct)e.value=pct;if(typeof sync==="function")sync(e)}
  if(v)v.textContent=UISPD.toFixed(2)+"×";
}
function setUiSpdPct(pct){
  pct=Math.max(UISPD_MIN*100,Math.min(UISPD_MAX*100,Math.round(+pct)||100));
  setUiSpd(pct/100);
  try{localStorage.setItem("uiSpd",String(pct/100))}catch(_){}
  syncUiSpdUI();
}
function bindUiSpd(){
  var e=document.getElementById("uiSpd");if(!e||e._ub)return;e._ub=1;
  e.addEventListener("input",function(){setUiSpdPct(e.value)});
  syncUiSpdUI();
}
(function(){var sv=null;try{sv=localStorage.getItem("uiSpd")}catch(_){}
  var n=parseFloat(sv);if(n>=UISPD_MIN&&n<=UISPD_MAX)setUiSpd(n)})();
/* 右下角设置面板（展开/收起）专用的额外倍率：只读 CSS 里的 --hub-spd，保证 JS 定时器与 CSS 动画同步 */
function themeT(ms){var k=parseFloat(getComputedStyle(document.documentElement).getPropertyValue("--theme-spd"))||1;return uiT(ms)/k}
function hubT(ms){var k=parseFloat(getComputedStyle(document.documentElement).getPropertyValue("--hub-spd"))||1;return uiT(ms)/k}
function isMobile(){return window.matchMedia("(max-width: 820px), (pointer: coarse)").matches}
