/* 性能优化开关：默认开启；用户关闭后恢复原始材质与装饰动画速度。 */
(function(){
  var saved=null;
  try{saved=localStorage.getItem('performanceMode')}catch(_){}
  var enabled=saved===null?true:saved==='1';
  document.body.classList.toggle('performance-mode',enabled);
})();
